            MV08.buyers_postal_code,
            MV08.buyers_country_code,
            MV08.business_telephone                                                                                                                 as business_telephone_3,
            MV08.routing_misc_information                                                                                                           as routing_misc_information_3,
            MV08.failed_vin

from        MO01
            left join
                MO01_MEX1
                on  MO01.response_id    = MO01_MEX1.response_id
                and MO01.index_MA01     = MO01_MEX1.index_MA01
                and MO01.index_MO01     = MO01_MEX1.index_MO01
            left join
                MO01_MK01
                on  MO01.response_id    = MO01_MK01.response_id
                and MO01.index_MA01     = MO01_MK01.index_MA01
                and MO01.index_MO01     = MO01_MK01.index_MO01
            left join
                MACL
                on  MO01.response_id    = MACL.response_id
                and MO01.index_MA01     = MACL.index_MA01
                and MO01.index_MO01     = MACL.index_MO01
            left join
                MC01
                on  MO01.response_id    = MC01.response_id
                and MO01.index_MA01     = MC01.index_MA01
                and MO01.index_MO01     = MC01.index_MO01
            left join
                MC01_MEX3
                on  MO01.response_id    = MC01_MEX3.response_id
                and MO01.index_MA01     = MC01_MEX3.index_MA01
                and MO01.index_MO01     = MC01_MEX3.index_MO01
            left join
                MC01_MEX4
                on  MO01.response_id    = MC01_MEX4.response_id
                and MO01.index_MA01     = MC01_MEX4.index_MA01
                and MO01.index_MO01     = MC01_MEX4.index_MO01
            left join
                MV01
                on  MO01.response_id    = MV01.response_id
                and MO01.index_MA01     = MV01.index_MA01
                and MO01.index_MO01     = MV01.index_MO01
            left join
                MV01_MEX3
                on  MO01.response_id    = MV01_MEX3.response_id
                and MO01.index_MA01     = MV01_MEX3.index_MA01
                and MO01.index_MO01     = MV01_MEX3.index_MO01
            left join
                MV01_MEX4
                on  MO01.response_id    = MV01_MEX4.response_id
                and MO01.index_MA01     = MV01_MEX4.index_MA01
                and MO01.index_MO01     = MV01_MEX4.index_MO01
            left join
                MV04
                on  MO01.response_id    = MV04.response_id
                and MO01.index_MA01     = MV04.index_MA01
                and MO01.index_MO01     = MV04.index_MO01
            left join
                MV08
                on  MO01.response_id    = MV08.response_id
                and MO01.index_MA01     = MV08.index_MA01
                and MO01.index_MO01     = MV08.index_MO01
order by    1,2,3
;